// JAH demo program — Feedback dynamics (toy)
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function negLoop(x0, steps){ var x=x0; for(var i=0;i<steps;i++) x=x+0.5*(10-x); return x; }
function posLoop(x0, steps){ var x=x0; for(var i=0;i<steps;i++) x=x+0.5*x; return x; }
check("negative feedback converges to 10", Math.abs(negLoop(0,20)-10)<0.01, true);
check("positive feedback diverges", posLoop(9.9,10)>20, true);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

